var BLASFEN_GA_ID='';document.addEventListener('DOMContentLoaded',function(){const toggle=document.querySelector('.nav-toggle');const nav=document.querySelector('.nav');if(toggle&&nav){toggle.addEventListener('click',function(){const isOpen=nav.classList.toggle('is-open');toggle.setAttribute('aria-expanded',isOpen?'true':'false');});document.addEventListener('click',function(e){if(nav.classList.contains('is-open')&&!nav.contains(e.target)&&!toggle.contains(e.target)){nav.classList.remove('is-open');toggle.setAttribute('aria-expanded','false');}});}
const root=document.documentElement;const btn=document.querySelector('.theme-toggle');const logo=document.querySelector('.brand__mark');function apply(theme){if(theme==='light')root.setAttribute('data-theme','light');else root.removeAttribute('data-theme');if(logo)logo.src=logo.src.replace(/logo(--Blasfen|-blasfen-claro)\.png/,theme==='light'?'logo--Blasfen.png':'logo-blasfen-claro.png');if(btn)btn.setAttribute('aria-label',theme==='light'?'Mudar para tema escuro':'Mudar para tema claro');const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',theme==='light'?'#FFFFFF':'#15171A');}
apply(root.getAttribute('data-theme')==='light'?'light':'dark');if(btn)btn.addEventListener('click',function(){const next=root.getAttribute('data-theme')==='light'?'dark':'light';apply(next);try{localStorage.setItem('blasfen-tema',next);}catch(e){}});var KEY='blasfen-cookies';function getConsent(){try{return localStorage.getItem(KEY);}catch(e){return null;}}
function setConsent(v){try{localStorage.setItem(KEY,v);}catch(e){}}
var gaLoaded=false;function loadAnalytics(){if(gaLoaded||!BLASFEN_GA_ID)return;gaLoaded=true;var sc=document.createElement('script');sc.async=true;sc.src='https://www.googletagmanager.com/gtag/js?id='+BLASFEN_GA_ID;document.head.appendChild(sc);window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments);};window.gtag('js',new Date());window.gtag('config',BLASFEN_GA_ID,{anonymize_ip:true});}
function track(name,params){if(window.gtag&&gaLoaded)window.gtag('event',name,params||{});}
var privacyHref=(document.querySelector('a[href$="politica-de-privacidade.html"]')||{}).getAttribute?document.querySelector('a[href$="politica-de-privacidade.html"]').getAttribute('href'):'politica-de-privacidade.html';function showBanner(){if(document.querySelector('.cookie-banner'))return;var box=document.createElement('div');box.className='cookie-banner';box.setAttribute('role','dialog');box.setAttribute('aria-live','polite');box.setAttribute('aria-label','Aviso de cookies');box.innerHTML='<p>Usamos cookies de medição para entender como o site é usado e melhorar o atendimento. Você pode aceitar ou recusar. Saiba mais na <a href="'+privacyHref+'">Política de Privacidade</a>.</p>'+'<div class="cookie-banner__actions"><button type="button" class="btn btn--ghost" data-c="recusado">Recusar</button><button type="button" class="btn btn--primary" data-c="aceito">Aceitar</button></div>';document.body.appendChild(box);box.addEventListener('click',function(e){var v=e.target.getAttribute&&e.target.getAttribute('data-c');if(!v)return;setConsent(v);box.remove();if(v==='aceito')loadAnalytics();});}
var consent=getConsent();if(consent==='aceito')loadAnalytics();else if(consent===null&&BLASFEN_GA_ID)showBanner();document.querySelectorAll('[data-cookie-settings]').forEach(function(b){b.addEventListener('click',function(){try{localStorage.removeItem(KEY);}catch(e){}showBanner();});});document.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[href]');if(!a)return;var h=a.getAttribute('href');if(h.indexOf('wa.me/')>-1)track('contato_whatsapp',{pagina:location.pathname});else if(h.indexOf('tel:')===0)track('contato_telefone',{pagina:location.pathname});else if(h.indexOf('mailto:')===0)track('contato_email',{pagina:location.pathname});});var form=document.querySelector('form.form');if(form)form.addEventListener('submit',function(){track('envio_formulario',{segmento:(form.segmento||{}).value});});if(document.body.hasAttribute('data-lead'))track('generate_lead',{metodo:'formulario'});});